function lower_case() {
 echo "$1" | tr '[:upper:]' '[:lower:]'
}

function exists_in_list() {
 LIST=$1; DELIMITER=$2; VALUE=$3
 LIST_WHITESPACES=$(echo $LIST | tr "$DELIMITER" " ")
 for x in $LIST_WHITESPACES; do
 if [ "$x" = "$VALUE" ]; then
 return 0
 fi
 done
 return 1
}

stop_words="of the a by is was for with were in on there this that at be been to or and if then else will would shall should could are am an I we you your me has he she his him her them their there"

function cleanToken() {
 local token="$1"
 local lower=$(lower_case "$token")
 if exists_in_list "$stop_words" " " "$lower"; then
 echo "not clean token"
 else
 echo "clean token"
 fi
}

function collapseToken() {
 echo "$1" | sed -e 's/[",.;:!?'\'' -]\+/ /g'
}
